class Polynomial:
    def __init__(self, coeffs):
        self.coeffs = coeffs
    def evaluate(self, x):
        result = 0
        for i, c in enumerate(self.coeffs):
            result += c * x ** i
        return result
    def degree(self):
        return len(self.coeffs) - 1

class Encoder:
    def __init__(self, shift):
        self.shift = shift
    def encode(self, text):
        result = ''
        for ch in text:
            if ch.isalpha():
                result += chr(ord(ch) + self.shift)
            else:
                result += ch
        return result
    def decode(self, text):
        result = ''
        for ch in text:
            if ch.isalpha():
                result += chr(ord(ch) - self.shift)
            else:
                result += ch
        return result

