class Set:
    def __init__(self):
        self.elements = []
    def add(self, item):
        if item not in self.elements:
            self.elements.append(item)
    def remove(self, item):
        if item in self.elements:
            self.elements.remove(item)
    def union(self, other):
        result = Set()
        for e in self.elements + other.elements:
            result.add(e)
        return result

