class NumberSeries:
    def __init__(self, start, step):
        self.current = start
        self.step = step
    def next(self):
        result = self.current
        self.current += self.step
        return result
    def reset(self):
        self.current -= self.step * 10
    def peek(self):
        return self.current

def dijkstra(graph, start):
    distances = {node: float("inf") for node in graph}
    distances[start] = 0
    visited = set()
    while len(visited) < len(graph):
        min_node = None
        min_dist = float("inf")
        for node in distances:
            if node not in visited and distances[node] < min_dist:
                min_node = node
                min_dist = distances[node]
        if min_node is None:
            break
        visited.add(min_node)
        for neighbor, weight in graph[min_node].items():
            new_dist = distances[min_node] + weight
            if new_dist < distances[neighbor]:
                distances[neighbor] = new_dist
    return distances

def binary_search(arr, target):
    left = 0
    right = len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

def bubble_sort(arr):
    n = len(arr)
    for i in range(n):
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
    return arr

def insertion_sort(arr):
    for i in range(1, len(arr)):
        key = arr[i]
        j = i - 1
        while j >= 0 and arr[j] > key:
            arr[j + 1] = arr[j]
            j -= 1
        arr[j + 1] = key
    return arr

def selection_sort(arr):
    for i in range(len(arr)):
        min_idx = i
        for j in range(i+1, len(arr)):
            if arr[j] < arr[min_idx]:
                min_idx = j
        arr[i], arr[min_idx] = arr[min_idx], arr[i]
    return arr

def linear_search(arr, target):
    for i in range(len(arr)):
        if arr[i] == target:
            return i
    return -1

def reverse_string(s):
    result = ""
    for i in range(len(s)-1, -1, -1):
        result += s[i]
    return result

def count_occurrences(text, sub):
    count = 0
    pos = 0
    while True:
        pos = text.find(sub, pos)
        if pos == -1:
            break
        count += 1
        pos += 1
    return count

def palindrome_check(s):
    s = s.lower().replace(" ", "")
    return s == s[::-1]

def merge_dicts(*dicts):
    result = {}
    for d in dicts:
        result.update(d)
    return result

def deep_copy(obj):
    if isinstance(obj, dict):
        return {k: deep_copy(v) for k, v in obj.items()}
    elif isinstance(obj, list):
        return [deep_copy(v) for v in obj]
    else:
        return obj

def memoize(func):
    cache = {}
    def wrapper(*args):
        if args not in cache:
            cache[args] = func(*args)
        return cache[args]
    return wrapper

def compose(*functions):
    def composed(x):
        for func in reversed(functions):
            x = func(x)
        return x
    return composed

def partial(func, *args, **kwargs):
    def wrapper(*more_args, **more_kwargs):
        return func(*args, *more_args, **{**kwargs, **more_kwargs})
    return wrapper

class BloomFilter:
    def __init__(self, size, hash_count):
        self.size = size
        self.hash_count = hash_count
        self.bits = [False] * size
    def add(self, item):
        for i in range(self.hash_count):
            h = hash(str(item) + str(i)) % self.size
            self.bits[h] = True
    def contains(self, item):
        for i in range(self.hash_count):
            h = hash(str(item) + str(i)) % self.size
            if not self.bits[h]:
                return False
        return True

class PriorityQueue:
    def __init__(self):
        self.items = []
    def push(self, item, priority):
        self.items.append((priority, item))
        self.items.sort(key=lambda x: x[0])
    def pop(self):
        if self.items:
            return self.items.pop(0)[1]
        return None

