class PriorityQueue:
    def __init__(self):
        self._items = []

    def push(self, item, priority):
        self._items.append((priority, item))
        self._items.sort(key=lambda x: x[0])

    def pop(self):
        if not self._items:
            return None
        return self._items.pop(0)[1]

    def is_empty(self):
        return len(self._items) == 0

