def build_graph(edges):
    graph = {}
    for u, v in edges:
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append(v)
        graph[v].append(u)
    return graph

def bfs_traverse(graph, start):
    visited = set()
    queue = [start]
    visited.add(start)
    result = []
    while queue:
        node = queue.pop(0)
        result.append(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
    return result

def dfs_traverse(graph, start):
    visited = set()
    stack = [start]
    result = []
    while stack:
        node = stack.pop()
        if node not in visited:
            visited.add(node)
            result.append(node)
            for neighbor in reversed(graph.get(node, [])):
                stack.append(neighbor)
    return result

def run_length_encode(data):
    if not data:
        return []
    result = []
    current = data[0]
    count = 1
    for item in data[1:]:
        if item == current:
            count += 1
        else:
            result.append((current, count))
            current = item
            count = 1
    result.append((current, count))
    return result

def shunting_yard(expression):
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
    output = []
    operators = []
    for token in expression:
        if token.isdigit():
            output.append(token)
        elif token in precedence:
            while (operators and operators[-1] != '(' and
                   precedence.get(operators[-1], 0) >= precedence[token]):
                output.append(operators.pop())
            operators.append(token)
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators[-1] != '(':
                output.append(operators.pop())
            operators.pop()
    while operators:
        output.append(operators.pop())
    return output

def lru_cache(capacity):
    cache = {}
    order = []
    def get(key):
        if key in cache:
            order.remove(key)
            order.append(key)
            return cache[key]
        return -1
    def put(key, value):
        if key in cache:
            order.remove(key)
        elif len(cache) >= capacity:
            oldest = order.pop(0)
            del cache[oldest]
        cache[key] = value
        order.append(key)
    return get, put

def trie_insert(root, word):
    node = root
    for char in word:
        if char not in node:
            node[char] = {}
        node = node[char]
    node['#'] = True

def segment_text(text, word_dict):
    n = len(text)
    dp = [False] * (n + 1)
    dp[0] = True
    for i in range(1, n + 1):
        for j in range(i):
            if dp[j] and text[j:i] in word_dict:
                dp[i] = True
                break
    return dp[n]

def find_median(nums):
    sorted_nums = sorted(nums)
    n = len(sorted_nums)
    if n % 2 == 1:
        return sorted_nums[n // 2]
    else:
        return (sorted_nums[n // 2 - 1] + sorted_nums[n // 2]) / 2

def paginate(items, page_size):
    pages = []
    for i in range(0, len(items), page_size):
        page = items[i:i + page_size]
        pages.append(page)
    return pages

def debounce(func, delay):
    timer = None
    def wrapper(*args, **kwargs):
        nonlocal timer
        if timer is not None:
            timer.cancel()
        timer = Timer(delay, func, args, kwargs)
        timer.start()
    return wrapper

def throttle(func, rate):
    last_called = 0
    def wrapper(*args, **kwargs):
        nonlocal last_called
        now = time.time()
        if now - last_called >= rate:
            last_called = now
            return func(*args, **kwargs)
    return wrapper

def singleton(cls):
    instances = {}
    def get_instance(*args, **kwargs):
        if cls not in instances:
            instances[cls] = cls(*args, **kwargs)
        return instances[cls]
    return get_instance

def observer_pattern():
    observers = []
    def subscribe(callback):
        observers.append(callback)
    def notify(data):
        for observer in observers:
            observer(data)
    return subscribe, notify

def memoize_fib():
    cache = {0: 0, 1: 1}
    def fib(n):
        if n not in cache:
            cache[n] = fib(n - 1) + fib(n - 2)
        return cache[n]
    return fib

def pipeline(*functions):
    def composed(input_val):
        result = input_val
        for func in functions:
            result = func(result)
        return result
    return composed

def flatten_dict(d, parent_key='', sep='.'):
    items = []
    for k, v in d.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep).items())
        else:
            items.append((new_key, v))
    return dict(items)

def group_by(items, key_func):
    groups = {}
    for item in items:
        key = key_func(item)
        if key not in groups:
            groups[key] = []
        groups[key].append(item)
    return groups

def curry(func):
    def curried(*args, **kwargs):
        if len(args) + len(kwargs) >= func.__code__.co_argcount:
            return func(*args, **kwargs)
        return lambda *args2, **kwargs2: curried(*args, *args2, **kwargs, **kwargs2)
    return curried

