def sudoku_valid(board, row, col, num):
    for i in range(9):
        if board[row][i] == num:
            return False
        if board[i][col] == num:
            return False
    box_row, box_col = 3 * (row // 3), 3 * (col // 3)
    for i in range(box_row, box_row + 3):
        for j in range(box_col, box_col + 3):
            if board[i][j] == num:
                return False
    return True

def infix_to_postfix(tokens):
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
    output = []
    op_stack = []
    for token in tokens:
        if token.isalpha():
            output.append(token)
        elif token == '(':
            op_stack.append(token)
        elif token == ')':
            while op_stack and op_stack[-1] != '(':
                output.append(op_stack.pop())
            op_stack.pop()
        else:
            while (op_stack and op_stack[-1] != '(' and
                   precedence.get(op_stack[-1], 0) >= precedence.get(token, 0)):
                output.append(op_stack.pop())
            op_stack.append(token)
    while op_stack:
        output.append(op_stack.pop())
    return output

def knn_classify(training_data, test_point, k=3):
    distances = []
    for data_point, label in training_data:
        dist = sum((a - b) ** 2 for a, b in zip(data_point, test_point)) ** 0.5
        distances.append((dist, label))
    distances.sort()
    nearest = distances[:k]
    labels = [label for _, label in nearest]
    return max(set(labels), key=labels.count)

